const $=s=>document.querySelector(s);let page='Overview',scenario='all',data=null,results=null,alertPick=null;const nav=['Overview','Register Agent','Agents','Assign Task','Live Gateway Feed','Alerts & Review','Scenario Runner','Evaluation','Audit & Baseline'];const icon={Overview:'◈','Register Agent':'♙',Agents:'⬡','Assign Task':'▤','Live Gateway Feed':'⌁','Alerts & Review':'⚠','Scenario Runner':'▶',Evaluation:'◷','Audit & Baseline':'▣'};async function req(url,opts={}){let headers={'Content-Type':'application/json',...(opts.headers||{})};if(url.startsWith('/api/')||url.startsWith('/alerts/')){let admin=sessionStorage.getItem('aw_admin_token')||'aw_admin_demo_token';sessionStorage.setItem('aw_admin_token',admin);headers['X-Admin-Token']=admin}let r=await fetch(url,{headers,...opts});let j=await r.json();if(!r.ok)throw Error(j.detail||'Request failed');return j}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pill(d){return `<span class="pill ${String(d).toLowerCase()}">${esc(d)}</span>`}function eventTable(events,detailed=false){return `<div class="tablewrap"><table><thead><tr><th>DECISION</th><th>TOOL / TARGET</th><th>POLICY CHECKS</th><th>TIME / LATENCY</th>${detailed?'<th>REASONS / EVIDENCE</th>':''}</tr></thead><tbody>${events.length?events.map(e=>`<tr><td>${pill(e.decision)}<small>${esc(e.id)}</small></td><td><b>${esc(e.tool)}</b><small>${esc(e.params?.resource_id||e.params?.target||e.params?.to||'—')}</small></td><td><div class="checkchips">${(e.checks||[]).map(c=>`<span class="check ${c.passed?'pass':'fail'}" title="${esc(c.detail)}">${c.passed?'✓':'×'} ${esc(c.name)}</span>`).join('')}</div></td><td>${new Date((e.timestamp||0)*1000).toLocaleTimeString()}<small>${e.latency_ms} ms</small></td>${detailed?`<td><small>${esc((e.reasons||[]).join('; ')||'No policy violation recorded')}</small><small>Confidence: ${Math.round((e.confidence||0)*100)}%</small></td>`:''}</tr>`).join(''):`<tr><td class="emptycell" colspan="${detailed?5:4}">No events yet. Run a scenario to populate the feed.</td></tr>`}</tbody></table></div>`}function metric(label,value,tone,sub){return `<div class="metric"><div class="metrichead"><span>${label}</span><i class="${tone}">●</i></div><strong>${value}</strong><small>${sub}</small></div>`}function title(t,s,action=''){return `<div class="paneltitle"><div><h2>${t}</h2><p>${s}</p></div>${action}</div>`}function shell(){ $('#root').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brandicon">⬡</div><div><b>AGENT<span>WATCH</span></b><small>SECURITY GATEWAY <i>v1.0</i></small></div></div><div class="workspace"><span class="live-dot"></span> LOCAL ENVIRONMENT <span class="env">DEV</span></div><div class="navlabel">WORKSPACE</div><nav>${nav.map(n=>`<button class="navitem ${page===n?'active':''}" data-page="${n}">${icon[n]} <span>${n}</span></button>`).join('')}</nav><div class="sidebarbottom"><div class="statusbox"><span class="live-dot"></span><div><b>Gateway operational</b><small>Rules engine · deterministic</small></div></div><small class="build">AGENTWATCH / BUILD 001</small></div></aside><main class="main"><header><div class="crumb">SECURITY OPERATIONS　›　<b>${page.toUpperCase()}</b></div><div class="headright"><span class="secure">🔒 Credentials stay server-side</span><button class="iconbtn" id="refresh">↻</button><div class="avatar">AD</div></div></header><section class="content"><div class="pageheading"><div><div class="eyebrow">AGENT CONTROL PLANE / PROCUREMENT</div><h1>${page}</h1><p>${({'Overview':'Monitor agent actions, policy decisions, and containment status.','Register Agent':'Issue a server-held identity and define the trust boundary.','Agents':'Inspect identity, role version, and restrictions.','Assign Task':'Bind the agent to a narrow, explicit outcome.','Live Gateway Feed':'Every proposed tool call is evaluated before execution.','Alerts & Review':'Investigate evidence, approve exact arguments, or contain risk.','Scenario Runner':'Reproduce deterministic attack and legitimate-use scenarios.','Evaluation':'Metrics are derived from locally executed scenario runs.','Audit & Baseline':'Inspect the audit trail and verified trust changes.'})[page]}</p></div><button class="outline" id="refresh2">↻ Refresh data</button></div><div id="message"></div><div id="pagebody"></div></section><footer><span>AGENTWATCH <b>●</b> LOCAL POLICY ENGINE</span><span>DETERMINISTIC RULES · NO API KEY REQUIRED</span></footer></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;shell();render()});$('#refresh').onclick=$('#refresh2').onclick=()=>load().then(render);render()}function panel(t,s,body,action=''){return `<div class="panel">${title(t,s,action)}${body}</div>`}function render(){if(!data)return $('#pagebody').innerHTML='<div class="panel">Connecting to local gateway…</div>';let ev=data.events||[],alerts=data.alerts||[],counts=data.counts||{},body='';if(page==='Overview'){body=`<div class="metrics">${metric('TOTAL EVALUATIONS',ev.length,'cyan','Recent gateway activity')}${metric('ALLOWED',counts.ALLOW||0,'green','Policy-compliant actions')}${metric('HELD / DENIED',(counts.HOLD||0)+(counts.DENY||0),'red','Blocked before execution')}${metric('OPEN ALERTS',alerts.filter(a=>a.status==='open').length,'purple','Require reviewer attention')}</div><div class="grid2">${panel('Decision distribution','Recorded policy outcomes',['ALLOW','HOLD','DENY','QUARANTINE'].map(d=>`<p>${pill(d)}　${counts[d]||0}</p>`).join(''))}${panel('Trust boundary','Server-side authority sources',`<div class="boundary"><div><b>Resource registry</b><small>Trusted classification</small></div><div><b>Approved role v1</b><small>Procurement Analyst</small></div><div><b>Gateway credentials</b><small>Never exposed to agent</small></div></div>`)}</div>${panel('Recent gateway events','Latest policy evaluations',eventTable(ev.slice(0,8)))}`}
else if(page==='Register Agent')body=`<div class="grid2">${panel('Register a new agent','Identity and permissions are issued by the gateway',`<label>Agent name<input id="agentname" value="Procurement Helper"></label><label>Owner / team<input id="owner" value="operator"></label><label>Approved role<select><option>Procurement Analyst · v1</option></select></label><p>Allowed tools</p><div class="chips">${['document.read','supplier.search','purchase.prepare','email.send'].map(x=>`<span class="chip">${x}</span>`).join('')}</div><p>Read scope</p><div class="chips">${['Quote-A','Quote-B','Vendor-Approved'].map(x=>`<span class="chip">${x}</span>`).join('')}</div><p>Approval rules: email.send, purchase.submit</p><button class="primary" id="register">Register agent</button>`)}${panel('Integration quick start','Call the gateway, not the protected tool',`<pre class="code">agent.call(tool="document.read",\n params={"resource_id":"Quote-A"})</pre><p class="muted">Credentials remain server-side. Agent tokens authenticate the caller.</p><button class="outline" id="integration">Run integration check</button>`)}</div>`;
else if(page==='Agents')body=panel('Registered agents','Current state and policy bindings',`<div class="tablewrap"><table><thead><tr><th>AGENT</th><th>OWNER</th><th>ROLE VERSION</th><th>STATE</th></tr></thead><tbody>${(data.agents||[]).map(a=>`<tr><td>${esc(a.name)}<small>${esc(a.id)}</small></td><td>${esc(a.owner)}</td><td>${esc(a.role)} / v${a.role_version}</td><td>${pill(a.state)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Restrictions apply per tool, so supplier reads can continue when email is blocked.</p>`);
else if(page==='Assign Task')body=panel('Create task authorization','Narrow scope beats broad permissions',`<label>Task instruction<textarea id="tasktext" rows="3">Compare Supplier A and Supplier B quotations and prepare a purchase request. Do not submit it.</textarea></label><p>Approved resources: Quote-A, Quote-B, Vendor-Approved</p><p>Authorized outcome: prepare purchase request, do NOT submit</p><p>Forbidden: HR reads, external exfiltration, purchase submission</p><button class="primary" id="storetask">Store task policy</button><pre id="taskout" class="code"></pre>`);
else if(page==='Live Gateway Feed')body=panel('Live evaluation feed','Ordered checks · pre-execution enforcement',eventTable(ev,true),`<button class="outline" id="testhr">Test HR denial</button>`);
else if(page==='Alerts & Review')body=`<div class="grid2">${panel('Alert queue',`${alerts.length} alert records`,alerts.length?alerts.map(a=>`<button class="alertrow" data-alert="${a.id}"><span class="alerticon">⚠</span><span><b>${esc(a.title)}</b><small>${esc(a.message)}</small><small>${esc(a.source_attribution)}</small></span>${pill(a.severity)}</button>`).join(''):'No alerts yet.')}${panel('Reviewer workbench','Evidence-based review',`<div id="alertdetail">Select an alert to inspect evidence.</div><label>Held event ID<input id="eventid" placeholder="evt-…"></label><div class="reviewactions"><button class="outline" id="approve">Approve exact args</button><button class="dangerbtn" id="stop">Stop session</button></div><label>Restrict tool<select id="restricttool"><option>email.send</option><option>purchase.prepare</option><option>supplier.search</option><option>document.read</option></select></label><button class="outline" id="restrict">Restrict selected tool</button>`)}</div>`;
else if(page==='Scenario Runner')body=panel('Deterministic scenario lab','No external API key required',`<div class="runnercontrols"><label>Scenario<select id="scenario"><option value="all">Run all 12 scenarios</option>${(window.scenarios||[]).map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><button class="primary" id="runscenario">▶ Run scenario</button></div><div class="callout"><b>Local scenario evidence only</b><p>Test pre-execution denial, exact-argument approvals, delegation, taint response, and containment.</p></div><div id="results">${results?formatResults(results):''}</div>`)+panel('Scenario catalog','12 included scenarios',`<div class="scenario-grid">${(window.scenarios||[]).map((s,i)=>`<div class="scenario-card"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(s.name)}</b><small>${esc(s.kind)}</small></div>`).join('')}</div>`);
else if(page==='Evaluation')body=`<div class="callout"><b>Computed from local scenario runs; no external benchmark results are claimed.</b><p>Metrics are calculated from locally recorded scenario-run records and gateway latency measurements.</p></div><div id="evalbody">Loading evaluation…</div>`;
else body=`<div class="metrics">${metric('AUDIT EVENTS',ev.length,'cyan','Recorded event records')}${metric('TAINT CANDIDATES','1','purple','Quote-B seeded injection')}${metric('BASELINE UPDATES','Human verified','green','No learning from denials')}</div>${panel('Audit log','Recent recorded actions',eventTable(ev,true))}${panel('Trusted baseline','Explicit human verification required',`<p class="muted">Baseline updates require three clean allowed events and explicit reviewer verification.</p><button class="primary" id="baseline">Verify clean baseline</button><div class="callout"><b>AgentDojo-style adapter stub</b><p>Extension point only; not a benchmark implementation.</p></div>`)}`;
$('#pagebody').innerHTML=body;wire();if(page==='Evaluation')req('/api/evaluation').then(e=>{$('#evalbody').innerHTML=`<div class="metrics">${metric('ATTACK SUCCESS RATE',(e.attack_success_rate*100).toFixed(1)+'%','red',`${e.scenario_runs} local scenario runs`)}${metric('LEGITIMATE COMPLETION',(e.legitimate_task_completion*100).toFixed(1)+'%','green','Legitimate scenario completion')}${metric('PRE-EXECUTION PREVENTION',(e.pre_execution_prevention_rate*100).toFixed(1)+'%','cyan','Attack scenarios prevented')}${metric('FALSE-POSITIVE RATE',(e.false_positive_rate*100).toFixed(1)+'%','purple','Incorrectly blocked legitimate runs')}</div><div class="grid2">${panel('Gateway latency','Recorded event evaluation duration',`<div class="latency"><div><small>AVERAGE</small><b>${e.gateway_latency_avg_ms} ms</b></div><div><small>P95</small><b>${e.gateway_latency_p95_ms} ms</b></div></div>`)}${panel('Detection delay','Prototype scenario records',`<div class="latency"><div><small>DETECTION DELAY</small><b>${e.detection_delay_ms} ms*</b></div></div><p class="muted">* Scenario runner currently records zero; this is not a production benchmark.</p>`)}</div>`}).catch(showError)}function formatResults(r){let xs=r.results||[r];return xs.map(x=>`<div class="resultrow"><span class="resulticon ${x.passed?'good':'bad'}">${x.passed?'✓':'×'}</span><div><b>${esc(x.name||x.scenario)}</b><small>${esc(JSON.stringify(x.steps||[]))}</small></div>${pill(x.passed?'PASS':'FAIL')}</div>`).join('')+`<p class="muted">${r.passed??xs.filter(x=>x.passed).length} / ${r.total??xs.length} scenarios passed.</p>`}function showError(e){let m=$('#message');if(m)m.innerHTML=`<div class="error">${esc(e.message)} <button onclick="this.parentElement.remove()">Dismiss</button></div>`;else if($('#root'))$('#root').innerHTML=`<div style="padding:24px;font-family:sans-serif;color:#f87171"><h3>AgentWatch Error</h3><p>${esc(e.message)}</p></div>`}async function act(fn){try{$('#message').innerHTML='<div class="loading">Processing gateway operation…</div>';await fn();await load();render()}catch(e){showError(e)}}async function wire(){let bind=(id,fn)=>{let x=$('#'+id);if(x)x.onclick=fn};bind('register',()=>act(async()=>{let a=await req('/api/agents',{method:'POST',body:JSON.stringify({name:$('#agentname').value,owner:$('#owner').value,role:'procurement:1'})});alert('Copy this one-time token: '+a.api_token)}));bind('integration',()=>act(async()=>{let r=await req('/gateway/call',{method:'POST',headers:{Authorization:'Bearer aw_demo_token'},body:JSON.stringify({tool:'document.read',params:{resource_id:'Quote-A'},task_id:'task-demo',session_id:'ui-check'})});alert('Integration check: '+r.decision)}));bind('storetask',()=>act(async()=>{let r=await req('/api/tasks',{method:'POST',body:JSON.stringify({agent_id:'agent-procurement',instruction:$('#tasktext').value,approved_resources:['Quote-A','Quote-B','Vendor-Approved'],authorized_outcome:'prepare purchase request, do NOT submit',forbidden_actions:['read HR data','send data externally','submit purchase'],approval_requirements:['email.send','purchase.submit']})});$('#taskout').textContent=JSON.stringify(r,null,2)}));bind('testhr',()=>act(async()=>{let r=await req('/gateway/call',{method:'POST',headers:{Authorization:'Bearer aw_demo_token'},body:JSON.stringify({tool:'document.read',params:{resource_id:'HR-Salary'},task_id:'task-demo',session_id:'ui-hr-test'})});alert('Decision: '+r.decision+'\n'+r.reasons.join('; '))}));bind('runscenario',()=>act(async()=>{results=await req('/api/scenarios/run',{method:'POST',body:JSON.stringify({scenario:$('#scenario').value})});$('#results').innerHTML=formatResults(results)}));document.querySelectorAll('[data-alert]').forEach(b=>b.onclick=async()=>{alertPick=await req('/alerts/'+b.dataset.alert+'/explain');$('#alertdetail').innerHTML=`<h3>${esc(alertPick.alert.title)}</h3><p>${esc(alertPick.alert.message)}</p><p class="source">${esc(alertPick.alert.source_attribution)}</p><pre class="code">${esc(JSON.stringify(alertPick.explanation,null,2))}</pre>`;$('#eventid').value=alertPick.event.id});bind('approve',()=>act(async()=>{await req('/api/review/approve',{method:'POST',body:JSON.stringify({event_id:$('#eventid').value,approver:'dashboard-reviewer'})});alert('Exact argument approval recorded')}));bind('stop',()=>act(async()=>req('/api/recovery',{method:'POST',body:JSON.stringify({step:'stop execution',session_id:'default',note:'Reviewer initiated stop'})})));bind('restrict',()=>act(async()=>{return await req('/api/restrictions',{method:'POST',body:JSON.stringify({agent_id:'agent-procurement',tool:$('#restricttool').value,reason:'Reviewer-selected selective containment'})})}));bind('baseline',()=>act(async()=>{let b=await req('/api/baselines/verify',{method:'POST'});alert('Baseline verified: '+JSON.stringify(b))}))}async function load(){data=await req('/api/overview');window.scenarios=await req('/api/scenarios')}load().then(shell).catch(showError);
